CREATE TABLE IF NOT EXISTS "__EFMigrationsHistory" (
    "MigrationId" character varying(150) NOT NULL,
    "ProductVersion" character varying(32) NOT NULL,
    CONSTRAINT "PK___EFMigrationsHistory" PRIMARY KEY ("MigrationId")
);

START TRANSACTION;
CREATE TABLE "Clientes" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Nombre" character varying(100) NOT NULL,
    "Telefono" character varying(20),
    "DeviceToken" text,
    "CreadoEn" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_Clientes" PRIMARY KEY ("Id")
);

CREATE TABLE "Tiendas" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Nombre" character varying(100) NOT NULL,
    "Slug" character varying(50) NOT NULL,
    "Direccion" character varying(200),
    "Telefono" character varying(20),
    "CreadaEn" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_Tiendas" PRIMARY KEY ("Id")
);

CREATE TABLE "Pedidos" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "TiendaId" integer NOT NULL,
    "ClienteId" integer,
    "ClienteNombre" character varying(100),
    "Estado" integer NOT NULL,
    "FormaPago" integer NOT NULL,
    "EstadoPago" integer NOT NULL,
    "Total" numeric(18,2) NOT NULL,
    "Observaciones" character varying(500),
    "CreadoEn" timestamp with time zone NOT NULL,
    "ActualizadoEn" timestamp with time zone,
    CONSTRAINT "PK_Pedidos" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Pedidos_Clientes_ClienteId" FOREIGN KEY ("ClienteId") REFERENCES "Clientes" ("Id"),
    CONSTRAINT "FK_Pedidos_Tiendas_TiendaId" FOREIGN KEY ("TiendaId") REFERENCES "Tiendas" ("Id") ON DELETE CASCADE
);

CREATE TABLE "Productos" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "TiendaId" integer NOT NULL,
    "Nombre" character varying(100) NOT NULL,
    "Descripcion" character varying(500),
    "Precio" numeric(18,2) NOT NULL,
    "Disponible" boolean NOT NULL,
    "ImagenUrl" character varying(500),
    "CreadoEn" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_Productos" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Productos_Tiendas_TiendaId" FOREIGN KEY ("TiendaId") REFERENCES "Tiendas" ("Id") ON DELETE CASCADE
);

CREATE TABLE "UsuariosTienda" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "TiendaId" integer NOT NULL,
    "Nombre" character varying(100) NOT NULL,
    "Email" character varying(150) NOT NULL,
    "PasswordHash" text NOT NULL,
    "Rol" integer NOT NULL,
    "Activo" boolean NOT NULL,
    "CreadoEn" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_UsuariosTienda" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_UsuariosTienda_Tiendas_TiendaId" FOREIGN KEY ("TiendaId") REFERENCES "Tiendas" ("Id") ON DELETE CASCADE
);

CREATE TABLE "ItemsPedido" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "PedidoId" integer NOT NULL,
    "ProductoId" integer NOT NULL,
    "Cantidad" integer NOT NULL,
    "PrecioUnitario" numeric(18,2) NOT NULL,
    CONSTRAINT "PK_ItemsPedido" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_ItemsPedido_Pedidos_PedidoId" FOREIGN KEY ("PedidoId") REFERENCES "Pedidos" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_ItemsPedido_Productos_ProductoId" FOREIGN KEY ("ProductoId") REFERENCES "Productos" ("Id") ON DELETE CASCADE
);

CREATE INDEX "IX_ItemsPedido_PedidoId" ON "ItemsPedido" ("PedidoId");

CREATE INDEX "IX_ItemsPedido_ProductoId" ON "ItemsPedido" ("ProductoId");

CREATE INDEX "IX_Pedidos_ClienteId" ON "Pedidos" ("ClienteId");

CREATE INDEX "IX_Pedidos_TiendaId" ON "Pedidos" ("TiendaId");

CREATE INDEX "IX_Productos_TiendaId" ON "Productos" ("TiendaId");

CREATE UNIQUE INDEX "IX_Tiendas_Slug" ON "Tiendas" ("Slug");

CREATE UNIQUE INDEX "IX_UsuariosTienda_Email" ON "UsuariosTienda" ("Email");

CREATE INDEX "IX_UsuariosTienda_TiendaId" ON "UsuariosTienda" ("TiendaId");

INSERT INTO "__EFMigrationsHistory" ("MigrationId", "ProductVersion")
VALUES ('20260917143531_EsquemaAnteriorInventario', '9.0.20');

COMMIT;
